               // tap an existing cut opening → edit it\n    if (oh) { selectOpening(oh); massing.dragging = { type: 'openSlide', bi: oh.bi, idx: oh.idx, moved: false }; return; }\n    const fp = massFaceAt(sx, sy);                      // extruded (solid) mass → recessed opening on the tapped face\n    if (fp && massing.masses[fp.bi] && !massing.masses[fp.bi]._wall) {\n      const u = faceUAt(sx, sy, massing.masses[fp.bi], fp.id);\n      if (placeOpeningOnFace(fp.bi, fp.id, u, mode)) { massing.selected = fp.bi; massHint((mode === 'door' ? 'Door' : 'Window') + ' placed \\u2014 recessed into the face'); }\n      return;\n    }\n    const bi = massAt(sx, sy);\n    if (bi < 0) { massHint('Tap a wall or mass to ' + (massing.cutMode ? 'cut' : 'place') + ' a ' + mode); return; }\n    if (massing.cutMode) cutOpening(sx, sy, bi, mode); else placeOpening(bi, mode);\n    return;\n  }\n  const hit = massAt(sx, sy);\n  if (t === 'select') {\n    // 1) a gizmo handle on the already-selected mass?\n    const hp = (massing.selected >= 0) ? gizmoPick(sx, sy) : null;\n    if (hp) {\n      massSnapshot();\n      const b = massing.masses[massing.selected];\n      const bt = massBaseTop(b), cx = bt.cx, cz = bt.cz, rot = b.rot || 0;\n      const fsx = (b.fsx != null ? b.fsx : (b.fscale != null ? b.fscale : 1));\n      const fsz = (b.fsz != null ? b.fsz : (b.fscale != null ? b.fscale : 1));\n      const gp = mGroundPick(sx, sy);\n      if (hp.type === 'height') {\n        massing.dragging = { type:'height', bi: massing.selected, sy0: sy, h0: b.h };\n        massHint('Drag up / down to push-pull height');\n      } else if (hp.type === 'rotate') {\n        massing.dragging = { type:'grotate', bi: massing.selected, cx, cz, rot0: rot, ang0: Math.atan2(gp.z - cz, gp.x - cx) };\n        massHint('Drag around to rotate');\n      } else if (hp.type === 'scale') {\n        massing.dragging = { type:'gscale', bi: massing.selected, cx, cz, fsx0: fsx, fsz0: fsz, r0: Math.max(0.05, Math.hypot(gp.x - cx, gp.z - cz)) };\n        massHint('Drag to scale the footprint');\n      } else if (hp.type === 'stretch') {\n        const cr = Math.cos(rot), sr = Math.sin(rot);\n        const proj = hp.axis === 'x' ? (gp.x - cx)*cr + (gp.z - cz)*sr : -(gp.x - cx)*sr + (gp.z - cz)*cr;\n        massing.dragging = { type:'gstretch', bi: massing.selected, cx, cz, rot0: rot, axis: hp.axis, fsx0: fsx, fsz0: fsz, ext0: Math.max(0.05, Math.abs(proj)) };\n        massHint('Drag to push / pull this side');\n      }\n      return;\n    }\n    // 2) otherwise select the tapped mass and move it on the ground\n    massing.selOpening = null;\n    massing.selected = hit;\n    if (hit >= 0) {\n      massSnapshot();\n      const g = mGroundPick(sx, sy);\n      const b = massing.masses[hit];\n      massing.dragging = { type:'move', axis:'ground', bi:hit, sx, sy, sy0:sy, gx0:g.x, gz0:g.z, bx0:b.x, bz0:b.z, baseY0:b.baseY||0, poly0: b.poly ? b.poly.map(p => ({ x:p.x, z:p.z })) : null };\n      massHint('Drag to move · grab a handle to push-pull, scale or rotate');\n    } else {\n      massHint('Tap a mass to select it');\n    }\n    refreshInspector();\n    renderMassing();\n    return;\n  }\n  if (t === 'remove') {\n    const oh = openingAt(sx, sy);\n    if (oh) { massing.selOpening = oh; deleteSelOpening(); return; }\n    if (hit >= 0) {\n      massSnapshot();\n      massing.masses.splice(hit, 1);\n      if (massing.selected === hit) massing.selected = -1;\n      else if (massing.selected > hit) massing.selected--;\n      if (massing.masses.length === 0) massing.baseAnchor = null;   // fresh anchor next time\n      massHint(massing.masses.length ? 'Removed · tap another to remove' : 'All masses removed');\n    } else {\n      massHint('Tap a mass to remove it');\n    }\n    refreshInspector();\n    renderMassing();\n    return;\n  }\n  if (t === 'move') {\n    massing.selected = hit;\n    if (hit >= 0) {\n      massSnapshot();\n      const g = mGroundPick(sx, sy);\n      const b = massing.masse